<?php
namespace App\Http\Controllers;
use App\Models\{Event, Facility, Region, SiteSetting, Sport, Testimonial};
use Illuminate\Http\Request;
use Inertia\Inertia;

class PublicController extends Controller
{
    private function shared(): array { return ['settings' => SiteSetting::pluck('value', 'key')]; }
    public function home() { return Inertia::render('public/home', [...$this->shared(), 'sports' => Sport::where('published', true)->orderBy('sort_order')->get(), 'facilities' => Facility::with(['region', 'sports'])->where('published', true)->where('featured', true)->orderBy('sort_order')->get(), 'events' => Event::with(['sport', 'facility'])->where('published', true)->where('status', '!=', 'draft')->where('starts_at', '>=', now()->subDay())->orderBy('starts_at')->take(3)->get(), 'regions' => Region::withCount('facilities')->where('published', true)->orderBy('sort_order')->get(), 'testimonials' => Testimonial::where('approved', true)->latest()->take(3)->get()]); }
    public function facilities(Request $request) { $query = Facility::with(['region', 'sports'])->where('published', true); if ($request->filled('q')) $query->where(fn($q) => $q->where('name', 'like', '%'.$request->q.'%')->orWhere('venue_type', 'like', '%'.$request->q.'%')); if ($request->filled('region')) $query->where('region_id', $request->region); if ($request->filled('sport')) $query->whereHas('sports', fn($q) => $q->where('sports.id', $request->sport)); return Inertia::render('public/facilities', [...$this->shared(), 'facilities' => $query->orderBy('sort_order')->paginate(9)->withQueryString(), 'regions' => Region::where('published', true)->get(), 'sports' => Sport::where('published', true)->get(), 'filters' => $request->only('q', 'region', 'sport')]); }
    public function facility(Facility $facility) { abort_unless($facility->published, 404); return Inertia::render('public/facility', [...$this->shared(), 'facility' => $facility->load(['region', 'sports', 'features', 'specifications', 'galleries']), 'related' => Facility::where('published', true)->whereKeyNot($facility->id)->take(3)->get()]); }
    public function sports() { return Inertia::render('public/sports', [...$this->shared(), 'sports' => Sport::with('category')->where('published', true)->orderBy('sort_order')->get()]); }
    public function sport(Sport $sport) { abort_unless($sport->published, 404); return Inertia::render('public/sport', [...$this->shared(), 'sport' => $sport->load(['category', 'facilities', 'events']), 'otherSports' => Sport::where('published', true)->whereKeyNot($sport->id)->take(6)->get()]); }
    public function events(Request $request) { $query = Event::with(['sport', 'facility'])->where('published', true)->where('status', '!=', 'draft'); if ($request->filled('sport')) $query->where('sport_id', $request->sport); if ($request->filled('status')) $query->where('status', $request->status); return Inertia::render('public/events', [...$this->shared(), 'events' => $query->orderBy('starts_at')->paginate(9)->withQueryString(), 'sports' => Sport::where('published', true)->get(), 'filters' => $request->only('sport', 'status')]); }
    public function event(Event $event) { abort_unless($event->published, 404); return Inertia::render('public/event', [...$this->shared(), 'event' => $event->load(['sport', 'facility']), 'moreEvents' => Event::with(['sport', 'facility'])->where('published', true)->whereKeyNot($event->id)->orderBy('starts_at')->take(2)->get()]); }
    public function regions() { return Inertia::render('public/regions', [...$this->shared(), 'regions' => Region::withCount('facilities')->with('facilities')->where('published', true)->get()]); }
    public function region(Region $region) { abort_unless($region->published, 404); return Inertia::render('public/region', [...$this->shared(), 'region' => $region->load('facilities')]); }
    public function inquiry(Request $request) { $data = $request->validate(['facility_id' => ['nullable', 'exists:facilities,id'], 'name' => ['required', 'string', 'max:120'], 'email' => ['nullable', 'email'], 'phone' => ['nullable', 'string', 'max:40'], 'message' => ['required', 'string', 'max:2000']]); \App\Models\Inquiry::create($data); return back()->with('success', 'Pesan Anda telah diterima.'); }
    public function testimonial(Request $request) { $data = $request->validate(['name' => ['required', 'string', 'max:120'], 'organization' => ['nullable', 'string', 'max:120'], 'rating' => ['required', 'integer', 'between:1,5'], 'review' => ['required', 'string', 'max:1000']]); Testimonial::create($data); return back()->with('success', 'Terima kasih. Ulasan menunggu moderasi.'); }
}
